local movedAt = 0
local function clampPosition(obj, x, y)
    return UDim2.fromOffset(math.clamp(x, 6, math.max(6, root.AbsoluteSize.X - obj.AbsoluteSize.X - 6)), math.clamp(y, 6, math.max(6, root.AbsoluteSize.Y - obj.AbsoluteSize.Y - 6)))
end
local function draggable(handle, object)
    local pointer, origin, start, moved
    connect(handle.InputBegan, function(e)
        if e.UserInputType == Enum.UserInputType.MouseButton1 or e.UserInputType == Enum.UserInputType.Touch then
            pointer, origin, start, moved = e, Vector2.new(e.Position.X, e.Position.Y), object.Position, false
        end
    end)
    connect(UIS.InputChanged, function(e)
        if pointer and (e == pointer or (pointer.UserInputType == Enum.UserInputType.MouseButton1 and e.UserInputType == Enum.UserInputType.MouseMovement)) then
            local delta = Vector2.new(e.Position.X, e.Position.Y) - origin
            if delta.Magnitude > 6 then moved = true end
            if moved then object.Position = clampPosition(object, start.X.Offset + delta.X, start.Y.Offset + delta.Y) end
        end
    end)
    connect(UIS.InputEnded, function(e)
        if e == pointer then
            if moved then movedAt = os.clock() end
            pointer = nil
        end
    end)
end
draggable(dragArea, window) draggable(floating, floating)
local function setOpen(value)
    S.open = value
    playSound("window")
    floating.Visible = not value
    if value then
        window.Visible = true
        tween(window, {GroupTransparency = 0}, 0.16)
    else
        tween(window, {GroupTransparency = 1}, 0.16)
        task.delay(0.17, function() if S.alive and not S.open then window.Visible = false end end)
    end
end
connect(minimize.Activated, function() setOpen(false) end)
connect(floating.Activated, function() if os.clock() - movedAt > 0.25 then setOpen(true) end end)
local positioned = false
local function layout()
    local available = root.AbsoluteSize
    if available.X < 1 or available.Y < 1 then return end
    local narrow = available.X < 600
    local w, h, side = narrow and 430 or 760, narrow and 620 or 510, narrow and 52 or 174
    window.Size = UDim2.fromOffset(w, h)
    uiScale.Scale = math.min(1, (available.X - 16) / w, (available.Y - 16) / h)
    sidebar.Size = UDim2.new(0, side, 1, -119)
    content.Position = UDim2.fromOffset(side + 24, 78)
    content.Size = UDim2.new(1, -side - 38, 1, -120)
    subtitle.Text = narrow and "DANCE STUDIO" or "DANCE STUDIO  /  BY BM"
    for i, b in ipairs(tabs) do b.Text = narrow and string.format("%02d", i) or string.format("%02d  %s", i, tabNames[i]) end
    if not positioned then
        window.Position = UDim2.fromOffset(math.max(6, (available.X - w * uiScale.Scale) / 2), math.max(6, (available.Y - h * uiScale.Scale) / 2))
        positioned = true
    else window.Position = clampPosition(window, window.Position.X.Offset, window.Position.Y.Offset) end
    floating.Position = clampPosition(floating, floating.Position.X.Offset, floating.Position.Y.Offset)
end
connect(root:GetPropertyChangedSignal("AbsoluteSize"), layout)
task.defer(layout)

local function trim(value) return tostring(value or ""):gsub("^%s+",""):gsub("%s+$","") end
local function validId(digits)
    if type(digits)~="string" or not digits:match("^%d+$") then return nil end
    digits=digits:gsub("^0+","")
    if digits=="" or #digits>16 or (#digits==16 and digits>"9007199254740991") then return nil end
    return digits
end
local function parseAnimationId(value)
    local text=trim(value)
    if #text>500 then return nil,"รหัสหรือลิงก์ยาวเกินไป" end
    local id=validId(text)
    if id then return id end
    local lower=text:lower()
    id=lower:match("^rbxassetid://(%d+)$")
    if id then return validId(id),"Animation ID ไม่ถูกต้อง" end
    local host,path=lower:match("^https?://([^/]+)(/.*)$")
    if host=="www.roblox.com" or host=="roblox.com" then
        if path:match("^/catalog/") then return nil,"ลิงก์ Catalog เป็นรหัสสินค้า • ต้องใช้ Animation ID ของท่านั้น" end
        id=path:match("^/library/(%d+)/") or path:match("^/library/(%d+)$")
        if not id and (path:match("^/asset/%?") or path:match("^/asset%?")) then
            id=path:match("[?&]id=(%d+)&") or path:match("[?&]id=(%d+)$")
        end
    elseif host=="create.roblox.com" then
        id=path:match("^/store/asset/(%d+)/") or path:match("^/store/asset/(%d+)$") or path:match("^/dashboard/creations/store/(%d+)/")
    end
    id=validId(id)
    if id then return id end
    return nil,"ใส่เลข Animation ID หรือ rbxassetid://ตามด้วยเลขครับ"
end
local function rigLabel(h)
    if not h then return "ไม่พบ" end
    if h.RigType==Enum.HumanoidRigType.R6 then return "R6" end
    if h.RigType==Enum.HumanoidRigType.R15 then return "R15" end
    return "Custom"
end
local function rigMatches(expected,actual) return expected=="Any" or expected==actual end
local function characterContext()
    local model=player.Character
    if not model or not model:IsDescendantOf(Workspace) then return nil,"รอตัวละครเกิดก่อนครับ" end
    local h=model:FindFirstChildOfClass("Humanoid") or model:FindFirstChildWhichIsA("Humanoid",true)
    if not h or h.Health<=0 then return nil,"ยังไม่พบตัวละครที่พร้อมเล่นท่า" end
    local animator=h:FindFirstChildOfClass("Animator")
    if not animator then return nil,"ตัวละครนี้ยังไม่มีระบบ Animator ที่รองรับ" end
    return {model=model,humanoid=h,animator=animator,rig=rigLabel(h)}
end
local function contextAlive(context)
    return S.alive and player.Character==context.model and context.model:IsDescendantOf(Workspace) and
        context.humanoid.Parent~=nil and context.humanoid.Health>0 and context.animator:IsDescendantOf(context.model)
end
local function disposeRecord(record)
    if not record or record.disposed then return end
    record.disposed=true
    for _,c in ipairs(record.connections or {}) do c:Disconnect() end record.connections={}
    if record.track then pcall(function() record.track:Stop(0) record.track:Destroy() end) end
    if record.animation then pcall(function() record.animation:Destroy() end) end
    S.retired[record]=nil
end
local function releaseRecord(record,fade)
    if not record or record.disposed then return end
    for _,c in ipairs(record.connections or {}) do c:Disconnect() end record.connections={}
    if not record.track or fade<=0 then disposeRecord(record) return end
    S.retired[record]=true
    pcall(function() record.track:Stop(fade) end)
    task.delay(fade+.1,function() disposeRecord(record) end)
end
local function cancelPending()
    S.generation=S.generation+1
    local old=S.pending S.pending=nil disposeRecord(old)
end
local function stopDance(message,immediate)
    cancelPending()
    local active=S.active S.active=nil
    releaseRecord(active,immediate and 0 or S.fadeTime)
    if immediate then
        local retiring={} for record in pairs(S.retired) do table.insert(retiring,record) end
        for _,record in ipairs(retiring) do disposeRecord(record) end
    end
    S.status=message or "หยุดแล้ว"
end
local function failLoad(record,message,detail)
    if S.pending~=record or S.generation~=record.token then disposeRecord(record) return end
    S.pending=nil disposeRecord(record)
    S.status=message..(S.active and " • ยังเล่นท่าเดิม" or "")
    if detail then S.lastError=tostring(detail) end
    notify(S.status)
end
local function requestPlay(value,name,expectedRig)
    if not S.alive then return false end
    local id,reason=parseAnimationId(value)
    if not id then notify(reason) return false end
    local context,why=characterContext()
    if not context then notify(why) return false end
    expectedRig=expectedRig or "Any"
    if not rigMatches(expectedRig,context.rig) then notify("ท่าระบุ "..expectedRig.." แต่ตัวละครเป็น "..context.rig) return false end
    if S.stopOnMove and context.humanoid.MoveDirection.Magnitude>.1 then notify("หยุดเดินก่อนเล่นท่า หรือปิดหยุดเมื่อเดินในหมวด 6") return false end
    cancelPending()
    local record={id=id,name=trim(name),expectedRig=expectedRig,context=context,token=S.generation,connections={}}
    if record.name=="" then record.name="ท่า "..id end
    S.pending=record S.status="กำลังโหลด "..record.name
    task.delay(CONFIG.LoadTimeout,function()
        if S.pending==record and S.generation==record.token then
            failLoad(record,"โหลดท่าไม่สำเร็จ • ตรวจรหัส สิทธิ์ และชนิดตัวละคร","Animation load timed out")
        end
    end)
    task.spawn(function()
        if record.disposed or S.pending~=record or S.generation~=record.token then disposeRecord(record) return end
        local ok,err=pcall(function()
            record.animation=Instance.new("Animation") record.animation.AnimationId="rbxassetid://"..id
            local track=context.animator:LoadAnimation(record.animation)
            -- LoadAnimation may yield in some clients: re-check cancellation before publishing the result.
            if record.disposed then pcall(function() track:Stop(0) track:Destroy() end) return end
            record.track=track
            while track.Length<=0 do
                if S.pending~=record or S.generation~=record.token or not contextAlive(context) then
                    if S.pending==record then S.pending=nil S.status="ยกเลิก: ตัวละครเปลี่ยนแล้ว" end
                    disposeRecord(record) return
                end
                task.wait(.05)
            end
            if S.pending~=record or S.generation~=record.token or not contextAlive(context) then
                if S.pending==record then S.pending=nil S.status="ยกเลิก: ตัวละครเปลี่ยนแล้ว" end
                disposeRecord(record) return
            end
            track.Priority=Enum.AnimationPriority.Action
            track.Looped=S.looped
            track:Play(S.fadeTime,1,S.playbackSpeed)
            local previous=S.active
            S.active=record S.pending=nil record.startedAt=os.clock() record.paused=false
            releaseRecord(previous,S.fadeTime)
            table.insert(record.connections,track.Ended:Connect(function()
                if S.active==record then S.active=nil S.status=S.pending and "กำลังโหลดท่าใหม่" or "เล่นจบแล้ว" end
                disposeRecord(record)
            end))
            table.insert(record.connections,context.humanoid.Died:Connect(function()
                if S.active==record then stopDance("หยุด: ตัวละครตาย",true) end
            end))
            S.successfulLoads=S.successfulLoads+1 S.status="กำลังเล่น "..record.name
        end)
        if not ok then
            if S.active==record then S.active=nil disposeRecord(record) S.lastError=tostring(err) S.status="หยุด: เล่นท่านี้ไม่ได้" notify(S.status)
            else failLoad(record,"โหลดท่านี้ไม่ได้ • ตรวจ Animation ID และสิทธิ์",err) end
        end
    end)
    return true
end
local function setPaused(value)
    local record=S.active
    if not record or not record.track.IsPlaying then notify("ยังไม่มีท่าที่กำลังเล่น") return false end
    local ok,err=pcall(function() record.track:AdjustSpeed(value and 0 or S.playbackSpeed) end)
    if not ok then S.lastError=tostring(err) notify("พักหรือเล่นต่อไม่ได้ครับ") return false end
    record.paused=value S.status=(value and "พักไว้: " or "กำลังเล่น ")..record.name return true
end
local function seekPercent(value)
    local record=S.active
    if not record or not record.track.IsPlaying or record.track.Length<=0 then notify("เล่นท่าก่อนเลื่อนตำแหน่งครับ") return false end
    local percent=tonumber(value)
    if not percent or percent~=percent or percent<0 or percent>100 then notify("ใส่ตำแหน่งตั้งแต่ 0 ถึง 100") return false end
    record.track.TimePosition=math.min(math.max(0,record.track.Length-.01),record.track.Length*percent/100)
    return true
end
local function applyPlayback()
    local record=S.active if not record then return end
    record.track.Looped=S.looped
    record.track:AdjustSpeed(record.paused and 0 or S.playbackSpeed)
end
local function currentPercent()
    local record=S.active
    return record and record.track.Length>0 and math.clamp(record.track.TimePosition/record.track.Length*100,0,100) or 0
end
local function decodeFavorites(data)
    if type(data)~="table" or data.version~=1 or type(data.favorites)~="table" then return nil,"รูปแบบไฟล์ไม่ถูกต้อง" end
    local count=0
    for key in pairs(data.favorites) do
        if type(key)~="number" or key%1~=0 or key<1 or key>CONFIG.MaxFavorites then return nil,"รายการท่าไม่ถูกต้อง" end count=count+1
    end
    if count~=#data.favorites then return nil,"รายการท่าไม่ต่อเนื่อง" end
    local out,seen={},{}
    for _,point in ipairs(data.favorites) do
        if type(point)~="table" or not validId(point.id) or type(point.name)~="string" or #point.name>120 or trim(point.name)=="" then return nil,"รหัสหรือชื่อท่าไม่ถูกต้อง" end
        if point.rig~="Any" and point.rig~="R6" and point.rig~="R15" then return nil,"ชนิดตัวละครไม่ถูกต้อง" end
        local id=validId(point.id) local key=id..":"..point.rig
        if seen[key] then return nil,"มีท่าซ้ำในไฟล์" end seen[key]=true
        table.insert(out,{id=id,name=point.name,rig=point.rig})
    end
    return out
end
local function saveFavorite(value,name,rig)
    local id,why=parseAnimationId(value) if not id then return false,why end
    if rig~="Any" and rig~="R6" and rig~="R15" then return false,"ชนิดท่าไม่ถูกต้อง" end
    name=trim(name) if name=="" then name="ท่า "..id end
    if #name>120 then return false,"ชื่อท่ายาวเกินไปครับ" end
    for i,point in ipairs(S.favorites) do
        if point.id==id and point.rig==rig then point.name=name S.selectedFavorite=i return true,"อัปเดตชื่อท่าโปรดแล้ว" end
    end
    if #S.favorites>=CONFIG.MaxFavorites then return false,"ท่าโปรดครบ "..CONFIG.MaxFavorites.." ท่าแล้ว" end
    table.insert(S.favorites,{id=id,name=name,rig=rig}) S.selectedFavorite=#S.favorites
    return true,"เพิ่มท่าโปรดแล้ว"
end
local function collectBuiltIns()
    local context,why=characterContext() if not context then return {},why end
    local animate=context.model:FindFirstChild("Animate")
    if not animate then return {},"เกมนี้ไม่แสดงรายการท่าในตัวละคร" end
    local queue={animate} local at=1 local out,seen={},{}
    while at<=#queue do
        local object=queue[at] at=at+1
        if object:IsA("Animation") then
            local id=parseAnimationId(object.AnimationId)
            local name=(object.Parent and object.Parent.Name or "").." / "..object.Name
            local lowered=name:lower()
            if id and not seen[id] and (S.showAllAnimations or lowered:find("dance",1,true) or lowered:find("emote",1,true)) then
                seen[id]=true table.insert(out,{id=id,name=name,rig=context.rig=="R6" and "R6" or context.rig=="R15" and "R15" or "Any"})
            end
        end
        for _,child in ipairs(object:GetChildren()) do if #queue>=CONFIG.MaxAnimationNodes then break end table.insert(queue,child) end
    end
    table.sort(out,function(a,b) return a.name<b.name end)
    return out,#queue>=CONFIG.MaxAnimationNodes and "อ่านรายการบางส่วน" or "อ่านจากตัวละครปัจจุบัน"
end

