local idInput,nameInput,rigButton,playInfo,favoriteBox,favoriteInfo,builtInBox,builtInInfo
local function readInputs()
    S.inputText=idInput.Text S.inputName=nameInput.Text
    return S.inputText,S.inputName,S.inputRig
end
local function showSelection(point)
    S.inputText=point.id S.inputName=point.name S.inputRig=point.rig
    idInput.Text=point.id nameInput.Text=point.name
    rigButton.Text="ชนิดท่า: "..(point.rig=="Any" and "ไม่ระบุ" or point.rig).."  ›"
end
local function playFromInput() return requestPlay(readInputs()) end
local function clearRows(box,connections)
    for _,c in ipairs(connections) do c:Disconnect() end
    for _,child in ipairs(box:GetChildren()) do if child:IsA("TextButton") then child:Destroy() end end
end
local function renderFavorites()
    if not favoriteBox then return end
    clearRows(favoriteBox,S.favoriteConnections) S.favoriteConnections={}
    favoriteInfo.Text=string.format("บันทึก %d / %d ท่า • แตะชื่อเพื่อเลือก",#S.favorites,CONFIG.MaxFavorites)
    for i,point in ipairs(S.favorites) do
        local b=make("TextButton",{Text=point.name.." • "..point.id..(S.selectedFavorite==i and " ✓" or ""),TextWrapped=true,TextSize=12,Font=Enum.Font.Gotham,
            TextColor3=C.text,BackgroundColor3=C.card,BorderSizePixel=0,Size=UDim2.new(1,0,0,44)},favoriteBox) corner(b,8)
        table.insert(S.favoriteConnections,b.Activated:Connect(function() playSound("click") S.selectedFavorite=i showSelection(point) renderFavorites() end))
    end
end
local function renderBuiltIns()
    if not builtInBox then return end
    clearRows(builtInBox,S.builtInConnections) S.builtInConnections={}
    local records,message=collectBuiltIns() S.builtIns=records
    builtInInfo.Text=string.format("พบ %d ท่า • %s\nแตะชื่อเพื่อใส่รหัส แล้วกดเล่นในหมวด 4",#records,message)
    for i=1,math.min(#records,40) do
        local point=records[i]
        local b=make("TextButton",{Text=point.name.." • "..point.id,TextWrapped=true,TextSize=12,Font=Enum.Font.Gotham,
            TextColor3=C.text,BackgroundColor3=C.card,BorderSizePixel=0,Size=UDim2.new(1,0,0,44)},builtInBox) corner(b,8)
        table.insert(S.builtInConnections,b.Activated:Connect(function() playSound("click") showSelection(point) selectTab(4) notify("ใส่รหัสแล้ว • กดเล่นท่าได้เลยครับ") end))
    end
end
