    stepper(p,"ระดับเสียงเมนู","volume",0,1,.05,function() for _,sound in pairs(sounds) do sound.Volume=S.volume end end)
    action(p,"ทดสอบเสียงเปิด / ปิด",function() playSound("window") end,true)
    mediaInfo=info(p,"กำลังเตรียมโลโก้และเสียง…")
    action(p,"สร้างรายงานตรวจท่า",function() diagnosticBox.Text=buildReport() end,true)
    diagnosticBox=make("TextBox",{Text="ถ้าท่าไม่เล่น ให้สร้างรายงานแล้วส่งภาพมาได้ครับ",TextColor3=C.muted,TextSize=11,Font=Enum.Font.Code,TextWrapped=true,MultiLine=true,ClearTextOnFocus=false,TextEditable=false,
        TextXAlignment=Enum.TextXAlignment.Left,TextYAlignment=Enum.TextYAlignment.Top,BackgroundColor3=C.card,Size=UDim2.new(1,0,0,180),BorderSizePixel=0},p) corner(diagnosticBox,10)
    make("UIPadding",{PaddingTop=UDim.new(0,10),PaddingBottom=UDim.new(0,10),PaddingLeft=UDim.new(0,10),PaddingRight=UDim.new(0,10)},diagnosticBox)
    action(p,"คัดลอกรายงาน",function()
        local report=buildReport() diagnosticBox.Text=report
        if type(setclipboard)=="function" then setclipboard(report) notify("คัดลอกแล้ว") else notify("เครื่องนี้ไม่มีคำสั่งคัดลอก ใช้ภาพหน้าจอแทนครับ") end
    end,true)
    action(p,"ปิด SATURN X DANCE",function() stop(false) end,true)
end

local quickBar=make("Frame",{Name="DanceControls",BackgroundTransparency=1,Size=UDim2.fromOffset(96,44),Position=UDim2.fromOffset(100,100),Visible=false},root)
local quickPlay=make("TextButton",{Text="▶",TextSize=21,Font=Enum.Font.GothamBold,TextColor3=C.text,BackgroundColor3=C.card,BackgroundTransparency=.15,
    BorderSizePixel=0,Size=UDim2.fromOffset(44,44),AutoButtonColor=false},quickBar) corner(quickPlay,24)
local quickStop=make("TextButton",{Text="■",TextSize=18,Font=Enum.Font.GothamBold,TextColor3=C.text,BackgroundColor3=C.card,BackgroundTransparency=.15,
    BorderSizePixel=0,Size=UDim2.fromOffset(44,44),Position=UDim2.fromOffset(50,0),AutoButtonColor=false},quickBar) corner(quickStop,24)
draggable(quickPlay,quickBar)
connect(quickPlay.Activated,function()
    if os.clock()-movedAt<=.25 then return end
    playSound("click") guarded(function()
        if S.pending then stopDance("ยกเลิกโหลดแล้ว") elseif S.active then setPaused(not S.active.paused)
        elseif trim(idInput.Text)~="" then playFromInput() else setOpen(true) selectTab(4) end
    end)
end)
connect(quickStop.Activated,function() playSound("click") stopDance("หยุดแล้ว") end)
stop=function(silent)
    if not S.alive then return end
    if not silent then playSound("window") end
    stopDance("ปิดแล้ว",true) S.alive=false
    for _,c in ipairs(S.connections) do c:Disconnect() end
    for _,c in ipairs(S.favoriteConnections) do c:Disconnect() end
    for _,c in ipairs(S.builtInConnections) do c:Disconnect() end
    sounds.click:Stop() gui:Destroy()
    if silent or S.mute then audioFolder:Destroy() else task.delay(3,function() audioFolder:Destroy() end) end
    if environment.SATURN_X_DANCE_STOP==stop then environment.SATURN_X_DANCE_STOP=nil end
end
environment.SATURN_X_DANCE_STOP=stop
connect(close.Activated,function() stop(false) end)
connect(gui.Destroying,function() if S.alive then stop(true) end end)
connect(player.CharacterRemoving,function() stopDance("หยุด: ตัวละครเปลี่ยนแล้ว",true) end)
connect(player.CharacterAdded,function() S.status="ตัวละครใหม่พร้อมแล้ว • เลือกท่าเพื่อเล่น" S.builtIns={} end)
connect(UIS.WindowFocusReleased,function() S.focused=false end)
connect(UIS.WindowFocused,function() S.focused=true end)
connect(UIS.InputBegan,function(e,processed)
    if processed or UIS:GetFocusedTextBox() then return end
    if e.KeyCode==Enum.KeyCode.RightShift then setOpen(not S.open) end
    if e.KeyCode==Enum.KeyCode.End or (S.hotkeys and e.KeyCode==Enum.KeyCode.X) then stopDance("หยุดแล้ว") end
    if S.hotkeys and e.KeyCode==Enum.KeyCode.P then
        if S.active then setPaused(not S.active.paused) elseif not S.pending then playFromInput() end
    end
end)
connect(RunService.RenderStepped,function(dt)
    if dt>0 then S.fps=S.fps*.9+math.min(999,1/dt)*.1 end
    if S.logoMotion and S.open then logo.Rotation=math.sin(os.clock()*.8)*3 end
    quickBar.Visible=S.quickControls and not S.open and S.focused
    quickBar.Position=clampPosition(quickBar,quickBar.Position.X.Offset,quickBar.Position.Y.Offset)
    quickPlay.Text=S.pending and "…" or (S.active and not S.active.paused and "Ⅱ" or "▶")
end)
task.spawn(function()
    local profileAt=0
    while S.alive do
        guarded(function()
            local active=S.active local pending=S.pending
            local record=active or pending
            if record and not contextAlive(record.context) then stopDance("หยุด: ตัวละครไม่พร้อม",true)
            elseif record and S.stopOnMove and record.context.humanoid.MoveDirection.Magnitude>.1 then stopDance("หยุดเมื่อเดิน") end
            active=S.active
            local detail=""
            if active then detail=string.format("\n%s • %.1f / %.1f วินาที • %.2fx",active.context.rig,active.track.TimePosition,active.track.Length,active.paused and 0 or S.playbackSpeed) end
            playInfo.Text=S.status..detail
            footer.Text=string.format("DANCE BETA 1.0.0 • FPS %.0f • %s",S.fps,S.pending and "กำลังโหลด" or active and (active.paused and "พักไว้" or "เล่นอยู่") or "พร้อม")
            if os.clock()-profileAt>=1 then
                profileAt=os.clock() local context,why=characterContext()
                profileLive.Text=context and string.format("ตัวละคร %s • HP %.0f\nโหลดท่าแล้ว %d ครั้ง\nผู้เล่นในเซิร์ฟเวอร์ %d",context.rig,context.humanoid.Health,S.successfulLoads,#Players:GetPlayers()) or why
            end
        end)
        task.wait(.15)
    end
end)
renderFavorites()

-- Decode exact attached files, then register locally only if the runtime supports it.
local function decode64(data)
    local alphabet, lookup = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/", {}
    for i = 1, #alphabet do lookup[string.byte(alphabet, i)] = i - 1 end
    local out = {}
    for i = 1, #data, 4 do
        local a, b, c, d = string.byte(data, i, i + 3)
        local n = (lookup[a] or 0) * 262144 + (lookup[b] or 0) * 4096 + (lookup[c] or 0) * 64 + (lookup[d] or 0)
        out[#out + 1] = string.char(math.floor(n / 65536) % 256)
        if c and c ~= 61 then out[#out + 1] = string.char(math.floor(n / 256) % 256) end
        if d and d ~= 61 then out[#out + 1] = string.char(n % 256) end
        if i % 65536 == 1 and i > 1 then task.wait() end
    end
    return table.concat(out)
end
local function assetId(value)
    if value == nil or value == "" then return nil end
    local v = tostring(value)
    return string.match(v, "^%d+$") and "rbxassetid://" .. v or v
end
local function registerAsset(kind, configured, ext)
    local configuredId = assetId(configured)
    if configuredId then return configuredId end
    local register = type(getcustomasset) == "function" and getcustomasset or (type(getsynasset) == "function" and getsynasset)
    if not register or type(writefile) ~= "function" then
        S.media[kind] = "ไม่รองรับไฟล์แนบ — ต้องตั้ง Roblox asset ID"
        return nil
    end
    local path = "SATURN_X_DANCE_v1_" .. kind .. ext
    local ok, id = pcall(function() writefile(path, decode64(EMBED[kind])) return register(path) end)
    if ok and type(id) == "string" then return id end
    S.media[kind] = "โหลดไม่ได้: " .. string.sub(tostring(id), 1, 70)
    return nil
end
local function updateMediaInfo()
    if S.alive then mediaInfo.Text = "โลโก้: " .. S.media.logo .. "\nเปิด/ปิด: " .. S.media.window .. "\nคลิก: " .. S.media.click end
end
task.spawn(function()
    local jobs = {{"logo", CONFIG.LogoAssetId, ".png"}, {"window", CONFIG.WindowSoundId, ".mp3"}, {"click", CONFIG.ClickSoundId, ".mp3"}}
    for _, job in ipairs(jobs) do
        if not S.alive then return end
        local kind = job[1]
        local id = registerAsset(kind, job[2], job[3])
        EMBED[kind] = nil
        if id and S.alive then
            local target
            if kind == "logo" then
                -- Remove both placeholders as soon as the real image is assigned.
                -- Rendering may succeed even when PreloadAsync fails or returns late.
                logoFallback.Visible = false
                floatingFallback.Visible = false
                logo.Image = id floating.Image = id target = logo
            else sounds[kind].SoundId = id target = sounds[kind] end
            S.media[kind] = "กำลังตรวจการโหลด"
            task.spawn(function()
                local ok = pcall(function() ContentProvider:PreloadAsync({target}) end)
                if not S.alive then return end
                if ok and target.IsLoaded then
                    S.media[kind] = "พร้อม"
                    if kind == "window" and S.open then playSound("window") end
                else S.media[kind] = "ไม่สำเร็จ / runtime หรือ asset permission ไม่รองรับ" end
                updateMediaInfo()
            end)
            task.delay(10, function()
                if S.alive and S.media[kind] == "กำลังตรวจการโหลด" then S.media[kind] = "โหลดช้า / ยังไม่ยืนยัน" updateMediaInfo() end
            end)
        end
        updateMediaInfo()
    end
end)
selectTab(4)
